from pathlib import Path
from collections import defaultdict,Counter
import re
ls=Path('candidate/statement-ledger.md').read_text().splitlines(); index={}; headings={}; primary=defaultdict(set); mentions=defaultdict(set); sec=None; malformed=[]
for n,l in enumerate(ls,1):
 if l.startswith('## '):
  sec=l[3:].split(' (',1)[0]
  if ' (' in l: headings[sec]=(n,l.split(' (',1)[1].rstrip(')'))
 if 512<=n<=688:
  cc=l.split('|'); lab=cc[1].strip().strip('"'`'"'); entries=re.findall(r'"'`([''^`]+)` '"\\((["'^)]+)'"\\)',cc[2]); index[lab]=(n,entries)
 if 693<=n<8712 and l.startswith('| ') and not l.startswith('| Paper label'):
  c=l[1:].split('|',1)[0].strip()
  if c.startswith('no direct label'): primary['no direct label'].add(sec)
  elif c.startswith('"'`'"'):
   primary[c.split('"'`'"')[1]].add(sec)
  else: malformed.append((n,c))
  for label in re.findall(r'"'`([A-Za-z]+:[''^`]+)`'"',c): mentions[label].add(sec)
problems=[]
for label,(n,entries) in index.items():
 ss=[s for s,c in entries]
 if len(ss)"'!=len(set(ss)): problems.append((n,'"'duplicate pointer'))
 if set(ss)"'!=primary[label]: problems.append((n,'"'PRIMARY mismatch',sorted(set(ss)"'^primary[label])))
 for s,cat in entries:
  heading=headings.get(s)
  if not heading or not heading[1].startswith(cat) or heading[1][len(cat):len(cat)+1] not in ('"'',':',' '): problems.append((n,'CATEGORY mismatch',s,cat,heading))
 print(f'{n}: {label}; primary sections={len(primary[label])}; category entries={len(entries)}; '+('MATCH' if set(ss)==primary[label] else 'MISMATCH'))
print('Primary-label/category problems:',problems,'malformed label cells:',malformed)
print('Index omissions if all explicit label-column uses are included:')
for lab,(n,entries) in index.items():
 if lab=='no direct label': continue
 omitted=mentions[lab]-{s for s,c in entries}
 if omitted: print(n,lab,sorted(omitted))
print('Labels only appearing non-leading in label columns:',sorted(set(mentions)-set(index)))
print('MANUSCRIPT LABEL SEARCHES:')
found=defaultdict(list)
for p in sorted(Path('manuscript').rglob('*.tex')):
 for n,l in enumerate(p.read_text().splitlines(),1):
  for lab in re.findall(r'\\\\label\\s*\\{(["'^}]+)'"\\}',l):
   if lab in index: found[lab].append((str(p),n,l.strip()))
for lab,(i,_) in index.items():
 if lab"'!='"'no direct label':
  for p,n,l in found[lab]: print(f'{i} {p}:{n}: {l}')
  if not found[lab]: print('MISSING',i,lab)
print('Label count:',len(found),'duplicate labels:',[(l,len(f)) for l,f in found.items() if len(f)>1])
PY"

